def ambientDualTruncation (φ : StrongDual 𝕜 (DFJPSum D)) (s : Finset ℤ) : StrongDual 𝕜 E :=
  ∑ j ∈ s, (lp2DualCoordinate φ j).comp
    (DFJPScale.continuousLinearEquiv D j).symm.toContinuousLinearMap

